import React from 'react'
import styled from 'styled-components'
import { FiCpu } from 'react-icons/fi'
import { FiMinusSquare, FiMaximize2 } from 'react-icons/fi'
import { IconButton } from '../../../styles/global'

interface ChatToolbarProps {
  onClearAll: () => void
  expanded: boolean
  panelWidth: number
  minimized: boolean
  onToggleMinimize: () => void
}

export const ChatToolbar: React.FC<ChatToolbarProps> = ({
  onClearAll,
  expanded,
  panelWidth,
  minimized,
  onToggleMinimize,
}) => {
  const explorerWidth = expanded ? 188 : 52
  return (
    <ToolbarContainer explorerWidth={explorerWidth} barWidth={panelWidth} minimized={minimized}>
      <SelectedPage>
        <FiCpu />
        Chat
      </SelectedPage>
      <ActionsContainer>
        <IconButton
          title={minimized ? 'Restore chat panel' : 'Minimize chat panel'}
          onClick={onToggleMinimize}
        >
          {minimized ? <FiMaximize2 /> : <FiMinusSquare />}
        </IconButton>
      </ActionsContainer>
    </ToolbarContainer>
  )
}

interface ToolbarContainerProps {
  explorerWidth: number
  barWidth: number
  minimized?: boolean
}

const ToolbarContainer = styled.div<ToolbarContainerProps>`
  display: flex;
  width: ${({ barWidth, minimized }) => (minimized ? 'auto' : `${barWidth}px`)};
  flex-direction: row;
  align-items: center;
  height: 32px;
  padding: 0;
  margin-left: 10px;
  margin-top: 10px;
  border-bottom: 1px solid #d0d0d0;
  border-top-left-radius: 10px;
  border-top-right-radius: 10px;
  border-bottom-left-radius: ${({ minimized }) => (minimized ? '10px' : '0px')};
  border-bottom-right-radius: ${({ minimized }) => (minimized ? '10px' : '0px')};
  background: #e0e0e5;
  position: relative;
`

const SelectedPage = styled.div`
  display: flex;
  width: 100%;
  align-items: center;
  gap: 10px;
  height: 35px;
  margin: 0px 10px;
`

const ActionsContainer = styled.div`
  display: flex;
  align-items: center;
  height: 35px;
`
