import React from 'react'
import styled from 'styled-components'
import { FiCpu, FiMenu } from 'react-icons/fi'
import { MdOutlineSummarize } from 'react-icons/md'
import { IconButton } from '../../../styles/global'
import mavis from '../../../assets/mavis.png'
import { TbPrompt } from 'react-icons/tb'
import { useChatAi } from '../context/ChatAiContext'

const modelsAvailable = ['gpt-5-mini', 'gpt-5.6-luna', 'gpt-5.6-terra', 'gpt-5.6-sol']

export const AIPanel: React.FC = () => {
  const [menuExpanded, setMenuExpanded] = React.useState(false)
  const [modelPickerOpen, setModelPickerOpen] = React.useState(false)
  const { setSystemPrompt, selectedModel, setSelectedModel } = useChatAi()

  const handleModelPickerClick = () => {
    const shouldOpen = !modelPickerOpen
    setModelPickerOpen(shouldOpen)
    if (shouldOpen) {
      setMenuExpanded(true)
    }
  }

  return (
    <Container expanded={menuExpanded}>
      <IconButton
        expanded={menuExpanded}
        title="Menu"
        onClick={() => setMenuExpanded(!menuExpanded)}
      >
        <FiMenu />
        {menuExpanded && <span>Mavis Settings</span>}
      </IconButton>

      <ModelPicker>
        <IconButton
          expanded={menuExpanded}
          title="Selecionar modelo de IA"
          onClick={handleModelPickerClick}
        >
          <FiCpu />

          {menuExpanded && <IconButtonLabel>AI Model</IconButtonLabel>}
        </IconButton>

        {modelPickerOpen && (
          <ModelDropdown>
            {modelsAvailable.map((model) => (
              <ModelOption
                key={model}
                className={selectedModel === model ? 'selected' : ''}
                onClick={() => setSelectedModel(model)}
                title={model}
              >
                <FiCpu />
                <span>{model}</span>
              </ModelOption>
            ))}
          </ModelDropdown>
        )}
      </ModelPicker>
      <IconButton expanded={menuExpanded} title="System Prompt">
        <TbPrompt />
        {menuExpanded && <IconButtonLabel>System Prompt</IconButtonLabel>}
      </IconButton>
      <IconButton expanded={menuExpanded} title="Summarize History">
        <MdOutlineSummarize />
        {menuExpanded && <IconButtonLabel>Summarize</IconButtonLabel>}
      </IconButton>

      <MavisImage src={mavis} draggable={false} visible={menuExpanded} />
    </Container>
  )
}

interface ContainerProps {
  expanded: boolean
}

const Container = styled.div<ContainerProps>`
  width: ${(props) => (props.expanded ? '180px' : '40px')};
  position: static;
  right: 0;
  top: 40px;
  height: 100%;
  border-left: 1px solid #d0d0d0;
  padding: 4px;
  overflow-y: none;
  overflow-x: visible;
  background: #f8f8f8;
  margin-left: 6px;
  transition: width 0.3s ease-in-out;
`

const ModelPicker = styled.div`
  position: relative;
  width: 100%;
`

const IconButtonLabel = styled.span`
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
`

const ModelDropdown = styled.div`
  position: absolute;

  top: 42px;
  left: 0;

  min-width: 160px;
  max-width: 280px;
  max-height: 280px;

  display: flex;
  flex-direction: column;
  gap: 2px;

  overflow-y: auto;

  background: white;
  border-radius: 14px;
  padding: 4px;

  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12), 0 2px 8px rgba(0, 0, 0, 0.08);

  z-index: 100;
`

const ModelOption = styled.span`
  width: 100%;
  min-height: 30px;

  display: flex;
  align-items: center;
  gap: 8px;

  text-align: left;

  border: none;
  border-radius: 10px;

  background: #f5f6f8;
  color: #444;

  padding: 8px 10px;

  cursor: pointer;
  transition: 0.2s;

  margin: 0 !important;

  overflow: hidden;

  span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &:hover {
    background: #eceff3;
  }

  &.selected {
    background: #4f46e5;
    color: white;
  }
`

interface MavisImageProps {
  visible: boolean
}

const MavisImage = styled.img<MavisImageProps>`
  position: absolute;
  width: 100px;
  height: auto;
  bottom: 0;
  right: 40px;
  z-index: 10;
  transition: opacity 0.1s ease-in-out, visibility 0s linear 0.3s;
  opacity: ${({ visible }) => (visible ? 1 : 0)};
  visibility: ${({ visible }) => (visible ? 'visible' : 'hidden')};
`
